import { describe, it, expect } from 'vitest';
import type { Cell } from '../engine/grid';
import { cellAppearance } from './cell-appearance';

// Story 21-S14 — only the word is highlighted. In the build phase, a cell
// of the cursor's row or column outside its word looks as it would outside
// the highlight while the cursor is in a word. With the cursor in no word,
// the line's off cells (empty, not a symmetric hint) are dull blue 'slot'.
// Do not edit this file to match an implementation.

const EMPTY: Cell = { kind: 'active', letter: null };
const LETTER: Cell = { kind: 'active', letter: 'A' };

function inLine(
  cell: Cell,
  { isOutsideWord, hasCursorWord, isSymmetricHint = false }: { isOutsideWord: boolean; hasCursorWord: boolean; isSymmetricHint?: boolean }
) {
  return cellAppearance({ cell, isSelected: false, isInSlot: true, isSymmetricHint, isOutsideWord, hasCursorWord });
}

describe('21-S14-1 the cell states of the cursor\'s line', () => {
  it('the cursor in a word: its cells blue-medium, as before', () => {
    expect(inLine(LETTER, { isOutsideWord: false, hasCursorWord: true })).toBe('slot-letter');
    expect(inLine(EMPTY, { isOutsideWord: false, hasCursorWord: true, isSymmetricHint: true })).toBe('slot-required');
  });

  it('the cursor in a word: the rest of the line as outside the highlight', () => {
    expect(inLine(LETTER, { isOutsideWord: true, hasCursorWord: true })).toBe('letter');
    expect(inLine(EMPTY, { isOutsideWord: true, hasCursorWord: true, isSymmetricHint: true })).toBe('symmetric-hint');
    expect(inLine(EMPTY, { isOutsideWord: true, hasCursorWord: true })).toBe('empty');
  });

  it('the cursor in no word: off cells dull blue, lettered cells and symmetric hints as outside', () => {
    expect(inLine(EMPTY, { isOutsideWord: true, hasCursorWord: false })).toBe('slot');
    expect(inLine(LETTER, { isOutsideWord: true, hasCursorWord: false })).toBe('letter');
    expect(inLine(EMPTY, { isOutsideWord: true, hasCursorWord: false, isSymmetricHint: true })).toBe('symmetric-hint');
  });

  it('the cursor cell stays selected, and Preview, the hints phase and play are unchanged', () => {
    expect(cellAppearance({ cell: LETTER, isSelected: true, isInSlot: true, isSymmetricHint: false, isOutsideWord: false, hasCursorWord: true })).toBe('selected');
    expect(cellAppearance({ cell: EMPTY, isSelected: false, isInSlot: true, isSymmetricHint: false, isOutsideWord: true, hasCursorWord: true, mode: 'preview' })).toBe('black');
    expect(cellAppearance({ cell: LETTER, isSelected: false, isInSlot: true, isSymmetricHint: false, isOutsideWord: true, hasCursorWord: true, isHintsPhase: true })).toBe('locked-letter');
    expect(cellAppearance({ cell: EMPTY, isSelected: false, isInSlot: true, isSymmetricHint: false, isOutsideWord: true, hasCursorWord: true, mode: 'play' })).toBe('letter');
  });
});
